-- Domain transition: additive auth-only namespace; old credentials and customer data untouched.
-- Additive only. Customer answers, request intents and existing submission IDs stay unchanged.
CREATE TABLE IF NOT EXISTS admin_dashboard_auth_challenges (id TEXT PRIMARY KEY,challenge TEXT NOT NULL,purpose TEXT NOT NULL CHECK(purpose IN ('registration','authentication')),expires_at INTEGER NOT NULL,used INTEGER NOT NULL DEFAULT 0 CHECK(used IN (0,1)),setup_hash TEXT);
CREATE INDEX IF NOT EXISTS admin_dashboard_challenges_expiry ON admin_dashboard_auth_challenges(expires_at);
CREATE TABLE IF NOT EXISTS admin_dashboard_credentials (id TEXT PRIMARY KEY,owner_email TEXT NOT NULL UNIQUE,user_handle TEXT NOT NULL,public_key BLOB NOT NULL,counter INTEGER NOT NULL,active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)),registration_flow TEXT NOT NULL UNIQUE REFERENCES admin_dashboard_auth_challenges(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS admin_dashboard_sessions (token_hash TEXT PRIMARY KEY,credential_id TEXT NOT NULL REFERENCES admin_dashboard_credentials(id),flow_id TEXT NOT NULL UNIQUE REFERENCES admin_dashboard_auth_challenges(id),expires_at INTEGER NOT NULL,new_counter INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS admin_dashboard_sessions_expiry ON admin_dashboard_sessions(expires_at);
CREATE TABLE IF NOT EXISTS admin_dashboard_auth_limits (bucket TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS admin_dashboard_auth_events (id INTEGER PRIMARY KEY AUTOINCREMENT,event TEXT NOT NULL,credential_id TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS admin_dashboard_register AFTER INSERT ON admin_dashboard_credentials BEGIN UPDATE admin_dashboard_auth_challenges SET used=1 WHERE id=NEW.registration_flow; INSERT INTO admin_dashboard_auth_events(event,credential_id,created_at) VALUES('registered',NEW.id,NEW.created_at); END;
CREATE TRIGGER IF NOT EXISTS admin_dashboard_session_open AFTER INSERT ON admin_dashboard_sessions BEGIN UPDATE admin_dashboard_auth_challenges SET used=1 WHERE id=NEW.flow_id; UPDATE admin_dashboard_credentials SET counter=NEW.new_counter WHERE id=NEW.credential_id; INSERT INTO admin_dashboard_auth_events(event,credential_id,created_at) VALUES('signed_in',NEW.credential_id,NEW.created_at); END;
CREATE TRIGGER IF NOT EXISTS admin_dashboard_session_close AFTER DELETE ON admin_dashboard_sessions BEGIN INSERT INTO admin_dashboard_auth_events(event,credential_id,created_at) VALUES('session_closed',OLD.credential_id,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
